ST.xhtml:p:
RTrigger(CLK := g_biZAbsExecute OR bAbsEXecute OR g_bZAbsExecute OR g_bZAbsMoveMControl);
RTrigger1(CLK := g_bAxisStopFlag);
RTrigger2(CLK := g_bAxisStopFlag_1);
FTRigger(CLK := g_biZAbsClose OR bAbsEXecute OR g_bZAbsExecute);

IF RTrigger.Q THEN
  g_boZAbsDone := FALSE;
  g_bZAbsDone := FALSE;
  bAbsDone := FALSE;
  IF g_biZAbsExecute THEN
    nAbsState := 1;
    dTargetPos := g_fiZAbsPosition; 
    dTargetVel := g_fiZAbsVelocity;
  ELSIF bAbsEXecute THEN
    nAbsState := 1;
    dTargetPos := dAbsPosition;
    dTargetVel := 0.0;
    bAbsEXecute := FALSE;
    IF g_bPowerOffMoveToTargetPosSetSpeedFlag THEN
      dTargetVel := g_dPowerOffMoveToTargetPosSpeed;
    END_IF;
  ELSIF g_bZAbsMoveMControl THEN
    g_bZAbsMoveMControl := FALSE;
    dTargetPos := g_dZAbsMovePositionM;
    dTargetVel := 0.0;
    IF g_bSetAuxiliaryAxisSpeed THEN
      dTargetVel := g_nAuxiliaryAxisSpeed;
      g_bSetAuxiliaryAxisSpeed := FALSE;
    END_IF;
    nAbsState := 1;
  ELSE
    nAbsState := 2;
    dTargetPos := g_fZAbsPosition;
    dTargetVel := g_fZAbsVelocity;
    g_bZAbsExecute := FALSE;
  END_IF;
  IF dTargetVel = 0.0 THEN
    dTargetVel := g_fZAxisVel;
  END_IF;
  bAbsClose := FALSE;
  (*运动防护,如果超过了最高点就到最高点*)
    IF dTargetPos > g_fLiftCoord THEN
      dTargetPos := g_fLiftCoord;
    END_IF;
    IF g_bZAxisIsOpenSoftWareLimit AND dTargetPos < g_dZAxisNegSoftWareValue THEN
      dTargetPos := g_dZAxisNegSoftWareValue +0.5;
    END_IF;
END_IF;

IF RTrigger1.Q THEN
  IF g_nAxisStopP = 1 THEN
    nAbsState := 21;
    g_bAxisStopFlag := FALSE;
  END_IF;
END_IF;

IF RTrigger2.Q THEN
  IF g_bAxisStopFlag_1 THEN
    nAbsState := 21;
    g_bAxisStopFlag_1 := FALSE;
  END_IF;
END_IF;

CASE nAbsState OF
  0:
    nAbsState := 0;
  1:
    g_ZMoveAbs.Execute := TRUE;
    g_ZMoveAbs.Velocity := dTargetVel;
    g_ZMoveAbs.Position := dTargetPos;
    IF g_ZMoveAbs.Done THEN
      g_ZMoveAbs.Execute := FALSE;
      g_boZAbsDone := TRUE;
      g_bZAbsDone := TRUE;
      bAbsDone := TRUE;
      nAbsState := 0;
      g_bZAxisMoveDoneM320 := TRUE;
	  g_bExecuteFinishedM203 := FALSE;
      M.ENABLE[203] := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nAbsState := 20;
    END_IF;
    IF g_ZMoveAbs.CommandAborted OR g_ZMoveAbs.Error THEN
      IF g_ZMoveAbs.CommandAborted THEN
		g_nZErrorIDToHmi := BOOL_TO_INT(g_ZMoveAbs.CommandAborted) + 1000;
      ELSE
        g_nZErrorIDToHmi := USINT_TO_INT(g_ZMoveAbs.ErrorId);  
      END_IF;  
      g_nFollowStateToHmi := g_nFollowState;
      g_ZMoveAbs.Execute := FALSE;
      g_boZAbsDone := FALSE;
      nAbsState := 0;
    END_IF;
  2:
    g_ZMoveAbs.Execute := TRUE;
    g_ZMoveAbs.Velocity := dTargetVel;
    g_ZMoveAbs.Position := dTargetPos;
    IF g_ZMoveAbs.Done THEN
      g_ZMoveAbs.Execute := FALSE;
      g_boZAbsDone := TRUE;
      g_bZAbsDone := TRUE;
      bAbsDone := TRUE;
      nAbsState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nAbsState := 21;
    END_IF;
    IF g_ZMoveAbs.CommandAborted OR g_ZMoveAbs.Error THEN
      IF g_ZMoveAbs.CommandAborted THEN
		g_nZErrorIDToHmi := BOOL_TO_INT(g_ZMoveAbs.CommandAborted) + 1000;
      ELSE
        g_nZErrorIDToHmi := USINT_TO_INT(g_ZMoveAbs.ErrorId);  
      END_IF;  
      g_nFollowStateToHmi := g_nFollowState;
      g_ZMoveAbs.Execute := FALSE;
      g_boZAbsDone := FALSE;
      nAbsState := 0;
    END_IF;
  20:
    g_ZMoveAbs.Execute := FALSE;
    g_ZMoveStop.Execute := TRUE;
    IF g_ZMoveStop.Done AND g_bPlcStartBuffer THEN
      g_ZMoveStop.Execute := FALSE;
      nAbsState := 1;
    END_IF;
    IF g_ZMoveStop.CommandAborted OR g_ZMoveStop.Error THEN
      g_ZMoveStop.Execute := FALSE;
      nAbsState := 0;
    END_IF;
  21:
    g_ZMoveAbs.Execute := FALSE;
    g_ZMoveStop.Execute := TRUE;
    IF g_ZMoveStop.Done THEN
      g_bFinishedM325_1 := FALSE;
	  M.ENABLE[325] := 0;
      g_ZMoveStop.Execute := FALSE;
      nAbsState := 0;
    END_IF;
    IF g_ZMoveStop.CommandAborted OR g_ZMoveStop.Error THEN
      g_ZMoveStop.Execute := FALSE;
      g_bFinishedM325_1 := FALSE;
	  M.ENABLE[325] := 0;
      nAbsState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nAbsState := 0;
  g_nZErrorIDToHmi := 0;
  g_ZMoveAbs.Execute := FALSE;
  g_ZMoveStop.Execute := FALSE;
END_IF;
